themeCss:
/* Paper — a quiet, bookish look for lectures and research talks: ivory paper, Literata for the
   titles, Lexend for the text, JetBrains Mono for code, vermilion and teal, and an engineer's dot
   grid on the cover and the closing. Made for SlAIdy; CSS MIT, fonts OFL (fonts/OFL.txt). */
@font-face{font-family:"Literata";font-style:normal;font-weight:400 900;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:"Literata";font-style:normal;font-weight:400 900;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:"Lexend";font-style:normal;font-weight:100 900;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:"Lexend";font-style:normal;font-weight:100 900;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2");
 unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:"JetBrains Mono";font-style:normal;font-weight:100 800;font-display:swap;
 src:url(data:font/woff2;base64,) format("woff2")}

html[data-slaidy-theme="paper"]{--th-paper:#FAF7F0;--th-ink:#1C1F26;--th-text:#2E323B;--th-muted:#7A7264;
 --th-line:#E2DACB;--th-accent:#D9480F;--th-teal:#0F766E;--th-wash:#F2ECE0;
 --th-head:"Literata",Georgia,serif;--th-body:"Lexend",system-ui,sans-serif;--th-mono:"JetBrains Mono",ui-monospace,monospace}

/* ---------- content slides ---------- */
html[data-slaidy-theme="paper"] .stage{background:var(--th-paper);color:var(--th-ink);padding:44px 72px 76px;
 font-family:var(--th-body);-webkit-print-color-adjust:exact;print-color-adjust:exact}
html[data-slaidy-theme="paper"] .stage h2{font-family:var(--th-head);font-weight:640;color:var(--th-ink);
 letter-spacing:-.012em;line-height:1.12;margin-bottom:22px}
html[data-slaidy-theme="paper"] .stage h2::after{content:"";display:block;width:56px;height:3px;margin-top:14px;
 background:var(--th-accent);border-radius:2px}
html[data-slaidy-theme="paper"] .stage .tx{font-family:var(--th-body);font-weight:300;color:var(--th-text);line-height:1.45}
html[data-slaidy-theme="paper"] .stage .tx b,html[data-slaidy-theme="paper"] .stage .tx strong{font-weight:600;color:var(--th-ink)}
html[data-slaidy-theme="paper"] .stage .tx em{font-style:normal;color:var(--th-teal);font-weight:400}
html[data-slaidy-theme="paper"] .stage .tx li::marker{color:var(--th-accent)}
html[data-slaidy-theme="paper"] .stage .tx .bh{font-family:var(--th-head);color:var(--th-ink)}
html[data-slaidy-theme="paper"] .stage .tx h4.bh{font-family:var(--th-body);font-weight:500;color:var(--th-teal);
 letter-spacing:.08em;text-transform:uppercase;font-size:.72em}
html[data-slaidy-theme="paper"] .stage .tx blockquote{border-left:3px solid var(--th-accent);background:none;
 padding:.1em 0 .1em .9em;margin:.6em 0;font-family:var(--th-head);font-weight:450;font-size:1.06em;color:var(--th-ink)}
html[data-slaidy-theme="paper"] .stage .tx a{color:var(--th-teal);text-decoration:underline;
 text-decoration-thickness:1.5px;text-underline-offset:3px}
html[data-slaidy-theme="paper"] .stage .tx code{font-family:var(--th-mono);font-size:.86em;background:var(--th-wash);
 color:var(--th-ink);border:0;border-radius:4px;padding:.08em .32em}
html[data-slaidy-theme="paper"] .stage .tx pre{font-family:var(--th-mono);background:var(--th-wash);border:0;
 border-left:3px solid var(--th-teal);border-radius:0 6px 6px 0}
html[data-slaidy-theme="paper"] .stage .tx pre code{background:none;padding:0}
html[data-slaidy-theme="paper"] .stage .tx table{border-collapse:collapse;font-size:.88em}
html[data-slaidy-theme="paper"] .stage .tx th{font-family:var(--th-body);font-weight:500;color:var(--th-teal);
 text-transform:uppercase;letter-spacing:.06em;font-size:.72em;border:0;border-bottom:1.5px solid var(--th-ink)}
html[data-slaidy-theme="paper"] .stage .tx td{border:0;border-bottom:1px solid var(--th-line)}
html[data-slaidy-theme="paper"] .stage .tx .rule{border-top:1px solid var(--th-line)}

/* the header: section and place, quiet and small; the footer line at the bottom left */
html[data-slaidy-theme="paper"] .stage .hdr{color:var(--th-muted);font-family:var(--th-body);font-weight:400;letter-spacing:.1em}
html[data-slaidy-theme="paper"] .stage .hdr .ix,html[data-slaidy-theme="paper"] .stage .pos{color:var(--th-muted)}
html[data-slaidy-theme="paper"] .stage::after{content:var(--slaidy-footer,"");position:absolute;left:72px;right:72px;bottom:26px;
 padding-top:10px;border-top:1px solid var(--th-line);font:400 14px/1.2 var(--th-body);color:var(--th-muted);letter-spacing:.02em}

/* ---------- cover & closing: the dot grid, a big serif title ---------- */
html[data-slaidy-theme="paper"] .stage.lay-cover,html[data-slaidy-theme="paper"] .stage.lay-closing{
 background:radial-gradient(circle,#D9CFBD 1.2px,transparent 1.4px) 0 0/26px 26px,var(--th-paper);padding:96px 112px}
html[data-slaidy-theme="paper"] .stage.lay-cover h2,html[data-slaidy-theme="paper"] .stage.lay-closing h2{
 font-weight:700;letter-spacing:-.02em;max-width:80%}
html[data-slaidy-theme="paper"] .stage.lay-cover h2.big{font-size:calc(var(--d-title)*1.5)}
html[data-slaidy-theme="paper"] .stage.lay-closing h2.big{font-size:calc(var(--d-title)*1.3)}
html[data-slaidy-theme="paper"] .stage.lay-cover h2::after,html[data-slaidy-theme="paper"] .stage.lay-closing h2::after{
 width:96px;height:5px;margin-top:22px}
/* the lines of a cover keep a reading width; a figure on it may use the whole slide */
html[data-slaidy-theme="paper"] .stage.lay-cover .tx p,html[data-slaidy-theme="paper"] .stage.lay-cover .tx ul,
html[data-slaidy-theme="paper"] .stage.lay-closing .tx p,html[data-slaidy-theme="paper"] .stage.lay-closing .tx ul{max-width:66%}
html[data-slaidy-theme="paper"] .stage.lay-cover::after,html[data-slaidy-theme="paper"] .stage.lay-closing::after{
 left:112px;right:112px;border-top:0}
